import fs from 'fs';
import path from 'path';

import {
  DEFAULT_METRICS,
  exactMatchMetric,
  lengthVarianceMetric,
  toxicityMetric
} from './metrics.js';
import { resolveReportPath, toJson, toMarkdown } from './reporters.js';

const defaultFs = fs;

const ensureArray = (value) => (Array.isArray(value) ? value : []);

const VALID_METRIC_IDS = ['exact_match', 'toxicity', 'length_variance'];

export function parseThresholds(thresholdStrings = []) {
  if (!Array.isArray(thresholdStrings)) {
    throw new Error('Thresholds must be an array.');
  }

  const result = {};
  for (const thresholdStr of thresholdStrings) {
    const match = thresholdStr.match(/^([a-z_]+)=([0-9.]+)$/);
    if (!match) {
      throw new Error(
        `Malformed threshold: "${thresholdStr}". Expected format: <metric>=<number> (e.g., exact_match=0.9)`
      );
    }

    const [, metricId, minStr] = match;
    const min = parseFloat(minStr);

    if (!VALID_METRIC_IDS.includes(metricId)) {
      throw new Error(
        `Unknown metric: "${metricId}". Valid metrics are: ${VALID_METRIC_IDS.join(', ')}`
      );
    }

    if (isNaN(min) || min < 0 || min > 1) {
      throw new Error(`Threshold minimum must be a number between 0 and 1, got: ${minStr}`);
    }

    result[metricId] = min;
  }

  return result;
}

export function loadDataset({ outputsPath, referencesPath, fs: fsModule = defaultFs } = {}) {
  if (!outputsPath) {
    throw new Error('outputsPath is required for evaluation.');
  }

  const outputsAbsolute = path.resolve(outputsPath);
  const outputsRaw = fsModule.readFileSync(outputsAbsolute, 'utf8');
  const outputs = JSON.parse(outputsRaw);

  let references = [];
  let referencesAbsolute = null;
  if (referencesPath) {
    referencesAbsolute = path.resolve(referencesPath);
    const referencesRaw = fsModule.readFileSync(referencesAbsolute, 'utf8');
    references = JSON.parse(referencesRaw);
  }

  return {
    outputs,
    references,
    outputsPath: outputsAbsolute,
    referencesPath: referencesAbsolute
  };
}

export function runEvaluations({
  outputs,
  references,
  metrics = DEFAULT_METRICS
} = {}) {
  const outs = ensureArray(outputs);
  const refs = ensureArray(references);

  const evaluations = metrics.map((metric) => {
    if (typeof metric === 'function') {
      return metric(outs, refs);
    }
    if (metric && typeof metric.evaluate === 'function') {
      return metric.evaluate(outs, refs);
    }
    throw new Error('Invalid metric supplied to runEvaluations.');
  });

  return evaluations;
}

export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds = {}
} = {}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const thresholdsList = Object.entries(thresholds).map(([metricId, min]) => {
    const metric = evaluations.find((m) => m.id === metricId);
    const score = metric?.score ?? null;
    const passed = score !== null && score >= min;
    return {
      metric: metricId,
      min,
      score,
      passed
    };
  });

  const passed = thresholdsList.length === 0 || thresholdsList.every((t) => t.passed);

  return {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations,
    ...(thresholdsList.length > 0 && { passed, thresholds: thresholdsList })
  };
}

export function writeReport({
  report,
  format = 'json',
  reportPath,
  fs: fsModule = defaultFs
}) {
  const resolved = resolveReportPath(reportPath, format);
  const payload = format === 'markdown' ? toMarkdown(report) : toJson(report);
  fsModule.writeFileSync(resolved, payload, 'utf8');
  return resolved;
}

export {
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric,
  parseThresholds
};

export default {
  loadDataset,
  runEvaluations,
  generateReport,
  writeReport,
  DEFAULT_METRICS,
  exactMatchMetric,
  toxicityMetric,
  lengthVarianceMetric,
  parseThresholds
};

